-- Travel Audit: initial schema.
-- Money is stored in integer minor units (cents). Ids are generated by the client (UUIDs)
-- so records created offline never collide. Rows are soft-deleted (deleted_at) so that
-- deletions sync like any other change. updated_at is always set by the server and is the
-- sync cursor.

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

create table public.trips (
  id          uuid primary key,
  owner_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name        text not null check (char_length(name) between 1 and 100),
  currency    text not null default 'USD' check (currency ~ '^[A-Z]{3}$'),
  archived    boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  deleted_at  timestamptz
);

-- People allowed to read a trip. Matched against the signed-in user's email.
create table public.trip_viewers (
  id          uuid primary key,
  trip_id     uuid not null references public.trips (id) on delete cascade,
  email       text not null check (email = lower(email) and email ~ '^[^@\s]+@[^@\s]+$' and char_length(email) <= 254),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  deleted_at  timestamptz
);

create table public.members (
  id          uuid primary key,
  trip_id     uuid not null references public.trips (id) on delete cascade,
  name        text not null check (char_length(name) between 1 and 50),
  bill_from   text not null default 'join' check (bill_from in ('join', 'start')),
  left_at     timestamptz,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  deleted_at  timestamptz
);

-- One expense, split equally among `participants` (shares[i] belongs to participants[i]).
-- `contributions` records who actually paid: { "<member id>": amount, ... }.
create table public.expenses (
  id             uuid primary key,
  trip_id        uuid not null references public.trips (id) on delete cascade,
  description    text not null default '' check (char_length(description) <= 200),
  amount_cents   bigint not null check (amount_cents > 0 and amount_cents <= 9007199254740991),
  paid_mode      text not null check (paid_mode in ('equal', 'single', 'custom')),
  payer_id       uuid,
  participants   uuid[] not null,
  shares         bigint[] not null,
  contributions  jsonb not null,
  occurred_at    timestamptz not null default now(),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  deleted_at     timestamptz
);

-- kind = 'debt':    from_member owes to_member.
-- kind = 'payment': from_member paid to_member (settles a debt).
create table public.transfers (
  id            uuid primary key,
  trip_id       uuid not null references public.trips (id) on delete cascade,
  kind          text not null check (kind in ('debt', 'payment')),
  from_member   uuid not null,
  to_member     uuid not null,
  amount_cents  bigint not null check (amount_cents > 0 and amount_cents <= 9007199254740991),
  description   text not null default '' check (char_length(description) <= 200),
  occurred_at   timestamptz not null default now(),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  deleted_at    timestamptz,
  check (from_member <> to_member)
);

create index trips_owner_idx on public.trips (owner_id);
create index trips_sync_idx on public.trips (updated_at, id);
create unique index trip_viewers_active_email_idx on public.trip_viewers (trip_id, email) where deleted_at is null;
create index trip_viewers_email_idx on public.trip_viewers (email) where deleted_at is null;
create index trip_viewers_sync_idx on public.trip_viewers (updated_at, id);
create index members_trip_idx on public.members (trip_id);
create index members_sync_idx on public.members (updated_at, id);
create index expenses_trip_idx on public.expenses (trip_id);
create index expenses_sync_idx on public.expenses (updated_at, id);
create index transfers_trip_idx on public.transfers (trip_id);
create index transfers_sync_idx on public.transfers (updated_at, id);

-- ---------------------------------------------------------------------------
-- Triggers: server-owned timestamps, immutable keys, accounting rules
-- ---------------------------------------------------------------------------

create or replace function public.touch_updated_at() returns trigger
language plpgsql set search_path = public as $$
begin
  new.updated_at := now();
  return new;
end $$;

create or replace function public.guard_trip() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.owner_id is distinct from old.owner_id then
    raise exception 'A trip cannot change owner' using errcode = '22023';
  end if;
  return new;
end $$;

create or replace function public.guard_trip_id() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.trip_id is distinct from old.trip_id then
    raise exception 'A record cannot move to another trip' using errcode = '22023';
  end if;
  return new;
end $$;

-- True when `member` is a member row of `trip`.
create or replace function public.is_trip_member(member uuid, trip uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.members m where m.id = member and m.trip_id = trip)
$$;

-- The same rules the app's audit enforces, so a buggy or tampered client cannot store
-- unbalanced books. Deleted rows are not re-validated (deleting a bad row must succeed).
create or replace function public.validate_expense() returns trigger
language plpgsql set search_path = public as $$
declare
  n            int := cardinality(new.participants);
  share_sum    numeric;
  share_min    bigint;
  share_max    bigint;
  bad_values   int;
  contrib_sum  numeric;
begin
  if new.deleted_at is not null then
    return new;
  end if;
  if n is null or n < 1 then
    raise exception 'Expense "%" must be shared by at least one member', new.description using errcode = '23514';
  end if;
  if coalesce(cardinality(new.shares), 0) <> n then
    raise exception 'Expense "%": participants and shares do not line up', new.description using errcode = '23514';
  end if;
  if (select count(distinct p) from unnest(new.participants) p) <> n then
    raise exception 'Expense "%": a member is listed more than once', new.description using errcode = '23514';
  end if;

  select sum(s), min(s), max(s) into share_sum, share_min, share_max from unnest(new.shares) s;
  if share_sum <> new.amount_cents or share_min < 0 or share_max - share_min > 1 then
    raise exception 'Expense "%": shares must be equal and add up to the amount', new.description using errcode = '23514';
  end if;

  if jsonb_typeof(new.contributions) <> 'object' then
    raise exception 'Expense "%": contributions must be an object', new.description using errcode = '23514';
  end if;
  select
    count(*) filter (where case when jsonb_typeof(value) = 'number'
                                then (value::text)::numeric < 0 or (value::text)::numeric <> trunc((value::text)::numeric)
                                else true end),
    coalesce(sum(case when jsonb_typeof(value) = 'number' then (value::text)::numeric end), 0)
  into bad_values, contrib_sum
  from jsonb_each(new.contributions);
  if bad_values > 0 then
    raise exception 'Expense "%": contributions must be whole, non-negative amounts', new.description using errcode = '23514';
  end if;
  if contrib_sum <> new.amount_cents then
    raise exception 'Expense "%": contributions add up to %, not %', new.description, contrib_sum, new.amount_cents using errcode = '23514';
  end if;

  if exists (
    select 1
    from (
      select unnest(new.participants) as member
      union select key::uuid from jsonb_each(new.contributions)
      union select new.payer_id where new.payer_id is not null
    ) referenced
    where not public.is_trip_member(referenced.member, new.trip_id)
  ) then
    raise exception 'Expense "%" refers to someone who is not a member of this trip', new.description using errcode = '23503';
  end if;
  return new;
end $$;

create or replace function public.validate_transfer() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.deleted_at is null and not (public.is_trip_member(new.from_member, new.trip_id)
                                     and public.is_trip_member(new.to_member, new.trip_id)) then
    raise exception 'Transfer refers to someone who is not a member of this trip' using errcode = '23503';
  end if;
  return new;
end $$;

create trigger trips_touch before insert or update on public.trips for each row execute function public.touch_updated_at();
create trigger trips_guard before update on public.trips for each row execute function public.guard_trip();

create trigger trip_viewers_touch before insert or update on public.trip_viewers for each row execute function public.touch_updated_at();
create trigger trip_viewers_guard before update on public.trip_viewers for each row execute function public.guard_trip_id();

create trigger members_touch before insert or update on public.members for each row execute function public.touch_updated_at();
create trigger members_guard before update on public.members for each row execute function public.guard_trip_id();

create trigger expenses_touch before insert or update on public.expenses for each row execute function public.touch_updated_at();
create trigger expenses_guard before update on public.expenses for each row execute function public.guard_trip_id();
create trigger expenses_validate before insert or update on public.expenses for each row execute function public.validate_expense();

create trigger transfers_touch before insert or update on public.transfers for each row execute function public.touch_updated_at();
create trigger transfers_guard before update on public.transfers for each row execute function public.guard_trip_id();
create trigger transfers_validate before insert or update on public.transfers for each row execute function public.validate_transfer();

-- ---------------------------------------------------------------------------
-- Row Level Security: the owner (bookkeeper) writes; invited viewers read.
-- ---------------------------------------------------------------------------

create or replace function public.is_trip_owner(trip uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.trips t where t.id = trip and t.owner_id = auth.uid())
$$;

create or replace function public.can_view_trip(trip uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_trip_owner(trip)
      or exists (
        select 1 from public.trip_viewers v
        where v.trip_id = trip
          and v.deleted_at is null
          and v.email = lower(coalesce(auth.jwt() ->> 'email', ''))
      )
$$;

alter table public.trips        enable row level security;
alter table public.trip_viewers enable row level security;
alter table public.members      enable row level security;
alter table public.expenses     enable row level security;
alter table public.transfers    enable row level security;

create policy trips_select on public.trips for select to authenticated
  using (owner_id = auth.uid() or public.can_view_trip(id));
create policy trips_insert on public.trips for insert to authenticated
  with check (owner_id = auth.uid());
create policy trips_update on public.trips for update to authenticated
  using (owner_id = auth.uid()) with check (owner_id = auth.uid());

-- Only the owner sees who else has access.
create policy trip_viewers_select on public.trip_viewers for select to authenticated
  using (public.is_trip_owner(trip_id));
create policy trip_viewers_insert on public.trip_viewers for insert to authenticated
  with check (public.is_trip_owner(trip_id));
create policy trip_viewers_update on public.trip_viewers for update to authenticated
  using (public.is_trip_owner(trip_id)) with check (public.is_trip_owner(trip_id));

create policy members_select on public.members for select to authenticated using (public.can_view_trip(trip_id));
create policy members_insert on public.members for insert to authenticated with check (public.is_trip_owner(trip_id));
create policy members_update on public.members for update to authenticated
  using (public.is_trip_owner(trip_id)) with check (public.is_trip_owner(trip_id));

create policy expenses_select on public.expenses for select to authenticated using (public.can_view_trip(trip_id));
create policy expenses_insert on public.expenses for insert to authenticated with check (public.is_trip_owner(trip_id));
create policy expenses_update on public.expenses for update to authenticated
  using (public.is_trip_owner(trip_id)) with check (public.is_trip_owner(trip_id));

create policy transfers_select on public.transfers for select to authenticated using (public.can_view_trip(trip_id));
create policy transfers_insert on public.transfers for insert to authenticated with check (public.is_trip_owner(trip_id));
create policy transfers_update on public.transfers for update to authenticated
  using (public.is_trip_owner(trip_id)) with check (public.is_trip_owner(trip_id));

-- No delete policies: rows are soft-deleted so the deletion reaches every device.
revoke all on public.trips, public.trip_viewers, public.members, public.expenses, public.transfers from anon;
revoke delete, truncate on public.trips, public.trip_viewers, public.members, public.expenses, public.transfers from authenticated;
grant select, insert, update on public.trips, public.trip_viewers, public.members, public.expenses, public.transfers to authenticated;

-- ---------------------------------------------------------------------------
-- Realtime: live updates for viewers (Realtime applies the select policies above).
-- ---------------------------------------------------------------------------
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.trips, public.members, public.expenses, public.transfers;
  end if;
end $$;
